#!/usr/bin/env python3
"""Deepen Jiajing governance from ritual politics to frontier systems."""
from __future__ import annotations
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
DATA = ROOT / "App/Resources/history.json"
NARRATION = ROOT / "App/Resources/narration_manifest.json"

def upsert(items, item, key="id"):
    for i, old in enumerate(items):
        if old.get(key) == item[key]: items[i] = item; return
    items.append(item)

def sec(i, title, text, sources, events, people):
    return {"id":i,"title":title,"text":text,"kind":"史实与解读","sources":sources,"events":events,"people":people}

def article(person, title, dek, sections):
    sources=[]
    for s in sections:
        for x in s["sources"]:
            if x not in sources: sources.append(x)
    return {"person":person,"title":title,"dek":dek,"sections":sections,"sources":sources}

def association(data, item):
    for i, old in enumerate(data["associations"]):
        if old["from"]==item["from"] and old["to"]==item["to"]: data["associations"][i]=item; return
    data["associations"].append(item)

def main():
    d=json.loads(DATA.read_text())
    src=[
      {"id":"v144_ms17","title":"《明史》卷17 · 世宗本纪一","url":"https://zh.wikisource.org/zh-hans/明史/卷17","note":"清修正史开放转录，用于核对嘉靖初政、大礼议、左顺门事件与早期诏令。纪年可靠性较高，廷杖人数和君臣言辞仍需与列传互证。"},
      {"id":"v144_ms18","title":"《明史》卷18 · 世宗本纪二","url":"https://zh.wikisource.org/zh-hans/明史/卷18","note":"用于核对河套案、庚戌之变、马市、北京外城及嘉靖大地震。灾亡八十三万余是官修汇总口径，并非现代人口学复核值。"},
      {"id":"v144_ms196","title":"《明史》卷196 · 张璁、桂萼、夏言传","url":"https://zh.wikisource.org/zh-hans/明史/卷196","note":"用于核对议礼诸臣的升迁、政策、司法介入与夏言河套案。列传褒贬鲜明，私人对话、动机和忠奸判断不直接当作事实结论。"},
      {"id":"v144_ms198","title":"《明史》卷198 · 翁万达传","url":"https://zh.wikisource.org/zh-hans/明史/卷198","note":"用于核对翁万达经营宣大、修墙设堡、情报与互市主张。工程里数和战功为官修奏报口径，规划、建成和长期有效须分开。"},
      {"id":"v144_ms204","title":"《明史》卷204 · 曾铣、丁汝夔等传","url":"https://zh.wikisource.org/zh-hans/明史/卷204","note":"用于核对河套方案、曾铣案、庚戌京防、军籍空额、军器发放与民兵。列传保存制度细节，也有为被害大臣辨冤的叙事立场。"},
      {"id":"v144_ms327","title":"《明史》卷327 · 鞑靼传","url":"https://zh.wikisource.org/zh-hans/明史/卷327","note":"用于核对俺答部活动、求贡互市与北部边境冲突。明朝文献使用的族称和战果来自本朝视角，不能代替蒙古内部政治与牧业经济。"},
    ]
    for x in src: upsert(d["sources"],x)
    people=[
      {"id":"m144_zhangcong","name":"张璁","call":"由大礼议进入内阁、同时改变礼制解释与用人司法的嘉靖重臣","temple":"—","era":"正德—嘉靖","reign":"1475—1539","summary":"四十七岁登进士第后，以“继统不继嗣”支持世宗尊崇生父，迅速进入中枢；清理庄田与镇守中官亦有政绩，但借考察、案件打击异己，留下程序争议。","parent":None,"sources":["v144_ms196","v144_ms17"],"kind":"议礼首辅","note":"后赐名孚敬。应同时记录其行政主张与报复性用权，不以议礼立场预先判定全部政策。","dynasty":"ming"},
      {"id":"m144_guie","name":"桂萼","call":"把大礼议、吏治考察与税粮边储放在同一改革议程中的大臣","temple":"—","era":"正德—嘉靖","reign":"1478—1531","summary":"因支持世宗礼制主张获重用，参与中枢用人和李福达案；同时提出灾区预免次年税粮、整顿盐引边储和容贫民耕种闲地等建议。","parent":None,"sources":["v144_ms196","v144_ms17"],"kind":"议礼与吏治大臣","note":"政策提议不等于均已执行；列传对其排斥异己的批评与具体制度建议应分别核对。","dynasty":"ming"},
      {"id":"m144_xiayan","name":"夏言","call":"从清庄田、复朝议走向首辅权力，并因河套方案被处死的嘉靖大臣","temple":"—","era":"正德—嘉靖","reign":"1482—1548","summary":"早年主张皇帝阅章召对、清查京卫冗员和归还民田，后受礼制工程与青词知遇入阁；再起后支持曾铣复套，与严嵩冲突，最终在政治化审判中被杀。","parent":None,"sources":["v144_ms196","v144_ms204","v144_ms18"],"kind":"首辅与礼制大臣","note":"既不能用其结局抹去早年改革，也不能因受害而忽略晚年任用、逮讯中的扩权。","dynasty":"ming"},
      {"id":"m144_zengxian","name":"曾铣","call":"提出恢复河套与长边墙方案、却在政策逆转后遭诛的三边总督","temple":"—","era":"嘉靖","reign":"1509—1548","summary":"处理辽东军乱、修临清外城后任三边总督，提出以六万锐卒和五十日粮进取河套、分段修墙；方案受夏言支持，后因皇帝疑虑与政治攻击被处死。","parent":None,"sources":["v144_ms204","v144_ms18"],"kind":"三边总督","note":"河套计划未实施，不能宣称必胜或以后入寇证明其必然正确；兵数、粮期和预算是计划口径。","dynasty":"ming"},
      {"id":"m144_qiuluan","name":"仇鸾","call":"由河套案脱罪、庚戌后骤掌京营，最终死后追戮的边将","temple":"—","era":"嘉靖","reign":"？—1552","summary":"曾镇甘肃并与曾铣冲突，借河套案出狱；庚戌之变后获授大将军、节制内外兵马，其部队扰民、冒功与压制独立民兵，死后被追究。","parent":None,"sources":["v144_ms18","v144_ms204","v144_ms198"],"kind":"边将与京营统帅","note":"生年不详。其失职和构陷有多篇列传互证，但死后定罪也处在政治翻转中，罪名须逐项辨析。","dynasty":"ming"},
      {"id":"m144_wengwanda","name":"翁万达","call":"以边墙、堡寨、侦候、军纪与有限互市经营宣大防线的边臣","temple":"—","era":"嘉靖","reign":"1498—1552","summary":"由广西地方治理和安南交涉转任宣大总督，主持修墙设堡、整顿将领和情报，反对仓促恢复河套并多次建议回应俺答贡市请求。","parent":None,"sources":["v144_ms198","v144_ms327"],"kind":"宣大总督","note":"工程与战功来自奏报；其互市主张是风险权衡，不等于无条件开放边境。","dynasty":"ming"},
      {"id":"m144_altan","name":"俺答汗","call":"在蒙古内部竞争、牧业需求与明朝封锁之间寻求贸易并持续用兵的土默特首领","temple":"—","era":"嘉靖—隆庆","reign":"1507—1582","summary":"达延汗之孙，控制土默特部并经营河套、丰州川一带，多次向明朝请求贡市，遭拒后与边境战争交替；1550年兵临北京，后于隆庆年间达成封贡。","parent":None,"sources":["v144_ms327","v144_ms18","v144_ms198"],"kind":"蒙古土默特首领","note":"明史称其为寇是明朝边政视角；应同时观察蒙古诸部竞争、畜产交换、板升聚落和明蒙双方暴力。","dynasty":"ming"},
    ]
    for x in people: upsert(d["people"],x)
    events=[
      {"id":"v144_left_gate","year":"1524年","sortYear":1524,"title":"左顺门伏阙与廷杖把礼制分歧变成人身惩罚","category":"政治","body":"群臣反对改变兴献帝称号，在左顺门集体哭谏。世宗下令逮捕、廷杖，官修本纪记一百三十四人下狱、十六人死于杖后。","impact":"人数为官修汇总，仍应逐名册核对；可以确认的是，礼学争议由奏议转成刑罚，改变了此后表达异议的成本。","people":["houcong","m144_zhangcong","m144_guie","m143_yangtinghe"],"sources":["v144_ms17","v144_ms196"],"kind":"大礼议与政治惩罚"},
      {"id":"v144_lifuda","year":"1526—1528年","sortYear":1527,"title":"李福达案复审牵动法司、言官与议礼阵营","category":"政治","body":"张璁、桂萼等推动重审李福达案，原审官员和反对者受到追究。案件真假、同名身份与地方审理交织，最后被纳入中枢阵营冲突。","impact":"不能仅凭某一派传记还原全部案情；制度问题在于首辅、言官和皇帝意向可越过稳定证据规则，扩大牵连。","people":["m144_zhangcong","m144_guie","houcong"],"sources":["v144_ms196","v144_ms17"],"kind":"司法与中枢权力"},
      {"id":"v144_estates_eunuchs","year":"1521—1530年代","sortYear":1528,"title":"清庄田与裁镇守中官尝试收回正德以来的特权","category":"经济","body":"嘉靖初清查勋戚、宫府庄田，夏言等将侵占民产归还；张璁推动裁撤部分镇守中官。改革试图减少土地投献和多头征取。","impact":"诏令与个案归还不等于所有土地完成清册；土地来源、租佃关系与地方执行决定居民是否真正减负。","people":["m144_zhangcong","m144_xiayan","houcong"],"sources":["v144_ms196"],"kind":"庄田与地方负担"},
      {"id":"v144_tax_salt_relief","year":"1520年代","sortYear":1529,"title":"预免税粮、盐引开中与闲地耕种进入救荒建议","category":"社会","body":"桂萼建议灾区可预免次年税粮，重整以盐引换边储的开中法，并允许贫民耕种部分墙边闲地，试图把赈济与生产恢复连接。","impact":"列传保存的是建议，执行范围不能夸大；免税、边储和土地使用会影响不同群体，不能合成单一惠政数字。","people":["m144_guie"],"sources":["v144_ms196"],"kind":"救荒与边储"},
      {"id":"v144_wall_network","year":"1544—1548年","sortYear":1546,"title":"翁万达以墙、堡、墩台和侦候组成宣大防御网络","category":"军事","body":"翁万达在大同、宣府主持分段筑墙、设堡与墩台，整顿守军离次和降人情报。第一阶段奏报含墙一百九十二里、堡七座、墩台百余。","impact":"这些是阶段性工程口径，不代表一条封闭长城完工；持续守备还需军粮、维修、道路与民夫成本。","people":["m144_wengwanda","m144_altan"],"sources":["v144_ms198"],"kind":"宣大边防系统"},
      {"id":"v144_trade_envoys","year":"1540年代","sortYear":1547,"title":"贡市使者被杀与互市拒绝加深边境报复循环","category":"经济","body":"俺答方面多次提出贡市，翁万达主张在可控制条件下回应；朝廷疑惧安全风险，既往来使又有被杀，谈判逐渐转向大规模侵掠。","impact":"贸易需求不是战争的唯一原因，也不能为掠夺开脱；但若只写军事入侵，会遗漏马匹、粮食、布帛与蒙古内部竞争对决策的影响。","people":["m144_wengwanda","m144_altan","houcong"],"sources":["v144_ms198","v144_ms327"],"kind":"边贸与冲突升级"},
      {"id":"v144_hetao_plan","year":"1546—1548年","sortYear":1547,"title":"曾铣提出复套与千五百里边墙，朝廷先奖后疑","category":"军事","body":"曾铣设想以六万锐卒携五十日粮进军河套，并分段修筑约一千五百里边墙；部分巡抚和翁万达质疑粮运、兵力与守成成本。","impact":"这是未实施方案，六万、五十日和二十万两初拨均属计划口径。以后边患不能反推方案必胜，反对者也不等于放弃边防。","people":["m144_zengxian","m144_xiayan","m144_wengwanda"],"sources":["v144_ms204","v144_ms198"],"kind":"河套战略争论"},
      {"id":"v144_hetao_trial","year":"1548年","sortYear":1548,"title":"河套政策逆转后，曾铣与夏言在政治化审判中被杀","category":"政治","body":"世宗转而质疑复套名义、军粮与成功把握，严嵩改称不可行；仇鸾在狱中奏劾，曾铣被改用交结近侍律处死，夏言随后被杀。","impact":"政策失误、私人报复与司法罪名不可混同。史料称受贿指控无证，应明确其为指控而非既定事实。","people":["m144_zengxian","m144_xiayan","m144_qiuluan","m40_yansong"],"sources":["v144_ms204","v144_ms196","v144_ms18"],"kind":"边策与司法"},
      {"id":"v144_gengxu_supply","year":"1550年","sortYear":1550,"title":"庚戌之变暴露军籍虚额、军器拖延与援军缺粮","category":"军事","body":"俺答军由古北口深入，京师戒严。丁汝夔列营应对，却发现禁军册籍虚额、老弱和被私人役使者多；武库中官索取常例，甲仗发放迟缓。","impact":"危机不能只归罪一名兵部尚书；军籍、仓储、情报、指挥和皇帝召对延迟共同构成失灵链。","people":["m144_altan","m144_qiuluan","m144_wengwanda","houcong"],"sources":["v144_ms204","v144_ms18"],"kind":"京师防务与后勤"},
      {"id":"v144_gengxu_people","year":"1550年","sortYear":1550,"title":"城内临时动员与城外掠夺把战争成本压向居民","category":"社会","body":"北京居民、武举应试者被动员登城，商大节募民兵四千；城外州县遭掠，仇鸾部队又扰民。战后朝廷赈济畿内并免部分税粮。","impact":"“京师未陷”不等于社会损失有限。守城者、难民、被征物资和军队扰民都应纳入战争史，伤亡不作无来源精确化。","people":["m144_qiuluan","m144_altan"],"sources":["v144_ms204","v144_ms18"],"kind":"居民动员与战后赈济"},
      {"id":"v144_horse_markets","year":"1551—1552年","sortYear":1551,"title":"宣大马市短暂开放后关闭，战争与贸易继续摇摆","category":"经济","body":"庚戌后朝廷在宣府、大同等处尝试马市，以交易缓和冲突并取得马匹；次年又因互信、越界和政治压力关闭。","impact":"开市不是永久和平，闭市也不能消除跨境交换。评估效果需看交易规则、参与部众和边民安全，而非只看诏令日期。","people":["m144_altan","m144_qiuluan","houcong"],"sources":["v144_ms18","v144_ms327"],"kind":"马市与边贸"},
      {"id":"v144_beijing_outer_city","year":"1550—1553年","sortYear":1553,"title":"庚戌危机推动北京外城从防务议案变成工程","category":"社会","body":"王忬等在庚戌后建议筑外郭。受财力与工期限制，最终先围合南郊一带，1553年告成，保护商业、坛庙与人口密集区。","impact":"外城不是一次完成今日北京形态；征地、运料、夫役和迁居同样是工程成本，防御收益与居民负担需同时记录。","people":["houcong","m144_qiuluan"],"sources":["v144_ms18","v144_ms204"],"kind":"城市防御与空间"},
      {"id":"v144_1556_earthquake","year":"1556年","sortYear":1556,"title":"嘉靖大地震重创陕西、山西与河南多地社会","category":"社会","body":"嘉靖三十四年十二月，陕西华州一带发生强震，山西、河南等地亦受灾，黄河、渭河水势和地表发生异常，窑居、城墙与房屋大量毁坏。","impact":"《明史》所记八十三万余死亡是官府汇总口径，可能含失踪与多地报数，不能当成现代精确统计；灾害影响还包括迁徙、饥馑、赋役与重建。","people":["houcong"],"sources":["v144_ms18"],"kind":"地震与灾后社会"},
    ]
    for x in events: upsert(d["events"],x)

    S196=["v144_ms196"]; S204=["v144_ms204"]; S198=["v144_ms198"]; S327=["v144_ms327"]
    readings=[
      article("m144_zhangcong","张璁：礼制论证怎样变成中枢权力","从四十七岁新科进士到首辅，他既推动清理特权，也让礼议阵营进入用人和司法。",[
        sec("v144_zc1","从‘继统不继嗣’进入嘉靖决策中心","1521年世宗以兴王世子身份入继大统，张璁援引礼经，主张继承皇位不等于改认孝宗为父，应尊生父兴献王。这套解释回应了皇帝最关切的家族名分，也挑战杨廷和等人的宗法方案。张璁不是凭一篇奏疏立即决定结果，朝廷经历称号、庙祀和礼仪多轮争论；但他由新科进士快速升迁，说明知识论证与最高权力需求结合，可以重排常规资历。理解大礼议应同时看礼学分歧、继承合法性和皇帝建立自主权威。",S196,["v2l_greatrites"],["houcong","m143_yangtinghe"]),
        sec("v144_zc2","左顺门以后，胜负不再只是经义之争","1524年群臣伏阙，皇帝下令逮捕、廷杖，张璁所支持的方案由此取得强制性优势。官修本纪记一百三十四人下狱、十六人杖后死亡，数字需与名册互证，但身体惩罚本身没有疑义。张璁不是每次廷杖的唯一决策者，最终命令来自皇帝；他也不能因曾受旧臣排斥就免除作为胜利阵营核心的责任。此后官员判断礼制问题时，面对的不只是学术说服，还包括职位、监禁与生命风险。",["v144_ms17","v144_ms196"],["v144_left_gate"],["m144_guie"]),
        sec("v144_zc3","清庄田、裁中官显示他不只有议礼一面","进入中枢后，张璁参与清理勋戚庄田、裁撤部分镇守中官，也曾反对因张延龄案扩大杀戮。这些政策回应正德后特权、地方多头征取和近侍网络问题。诏令不能证明所有被占土地都归还，镇守岗位撤销也可能以其他差遣重现；但若只以‘议礼新贵’概括他，会遗漏实际行政。评价应逐项考察谁获益、谁执行、是否形成清册，而不是把一位大臣的全部措施打包成忠或奸。",S196,["v144_estates_eunuchs"],["m144_xiayan"]),
        sec("v144_zc4","李福达案暴露司法被阵营化的危险","李福达身份与旧案本有复杂疑点，张璁、桂萼推动重审后，原审官员和反对者遭追责，争论又与大礼议旧怨重合。列传站在批评张璁的角度，不能据其叙事直接判定全部案情；同样也不能因为名义上是复审，就忽略首辅和皇帝意向对法司的压力。可确认的制度问题是证据审查、官员考察与政治立场互相捆绑，案件容易从纠错变成清算。司法可信度取决于程序能否承受权势者不满意的结论。",S196,["v144_lifuda"],["m144_guie"]),
        sec("v144_zc5","廉洁与报复性用权可以同时存在","《明史》称张璁自奉较清，却又记其考察官员、排斥异己和反复升黜。个人不聚敛不等于权力使用天然公正；反之，政治手段严厉也不必否定每项财政与行政措施。嘉靖初政的关键变化，是皇帝借议礼新人绕开旧内阁，再逐步把新人也置于反复恩威之下。张璁晚年多次进退，说明依赖个人知遇的权势缺少稳定边界。他的经历适合用来观察制度，而不是制作简单人物榜。",S196,["v144_lifuda","v144_estates_eunuchs"],["houcong","m144_xiayan"]),
      ]),
      article("m144_guie","桂萼：强硬议礼者也曾提出具体民生方案","他既借考察和案件压制异议，也把税粮、盐法、边储与贫民土地写进奏议。",[
        sec("v144_ge1","与张璁并进，不等于两人始终完全相同","桂萼与张璁共同支持世宗尊崇生父，因而在旧臣反对中迅速获用。他善于从礼经和制度先例为皇帝提供论证，也主动攻击反对者。两人常被合称议礼新贵，但官职、政策和人际关系并非完全同步。把他们视作一个符号，会掩盖具体奏议怎样进入吏部、法司和财政。更重要的是，皇帝才是礼制改变与惩罚的最终授权者，不能用近臣承担全部责任来淡化君权。",S196,["v2l_greatrites","v144_left_gate"],["m144_zhangcong","houcong"]),
        sec("v144_ge2","预免次年税粮是把救荒时间向前移动","桂萼提出灾伤严重时可预先蠲免下一年度税粮，使农户不必等到来年再申报。他又关注贫民耕种墙边闲地，希望把临时赈济与恢复生计结合。列传保存的是政策主张，不能写成全国普遍实施；闲地也可能涉及军防、原住户与地方权属。其价值在于提醒救荒不只发粮，还需减少未来债务和赋役压力。检验成效要看地方勘灾、免额是否落实及弱势者能否取得土地。",S196,["v144_tax_salt_relief"],[]),
        sec("v144_ge3","盐引开中连接商人运输、边仓和军粮","他主张整顿开中，让商人输粮边地后取得盐引，以恢复边储。制度可以利用商业运输能力，却也可能因盐引积压、权贵占额和价格变化，把风险转给普通商人、灶户与边军。‘恢复旧法’并不自动产生旧日效果，交通、边镇需求和盐场产量均已变化。讨论桂萼经济主张，应把制度链条拆开，而不是只用重农或理财一个标签。",S196,["v144_tax_salt_relief"],["m144_wengwanda"]),
        sec("v144_ge4","用考察清吏治，也可能把异议变成不合格","桂萼进入吏部后强调考核官员，并借大礼议后的权势排斥政敌。官员考察本有整顿怠政与贪腐的正当目的，但若标准与个人阵营重合，正常监督便会失去可信度。他曾推荐王守仁，后来又参与攻击，显示关系会随政治需要改变。不能因某人后世声望高就倒推每次推荐都纯属知人，也不能把每次罢黜都视为行政考绩。关键在证据、复核与被考察者能否申辩。",S196,["v144_lifuda"],["m40_wangshouren","m144_zhangcong"]),
        sec("v144_ge5","把政策与权力方式分开，人物才不扁平","桂萼的税粮、盐法与贫民土地建议显示议礼阵营并非只有礼制口号；他在李福达案和用人中的做法又说明有具体政策能力并不保证遵守程序。史书因其骤贵而多负面评价，也可能用结局组织性格。可靠写法不是替他翻案，而是逐项注明提议、执行和结果，并把无法证实的动机留作史家判断。这样才能看到嘉靖改革为何既有清理旧弊的动力，又迅速产生新的权力失衡。",S196,["v144_tax_salt_relief","v144_lifuda"],["m144_zhangcong","houcong"]),
      ]),
      article("m144_xiayan","夏言：从归还民田到河套案，一位首辅的上升与失守","早年强调召对、朝议和清理特权，晚年却在权力竞争与激进边策中走向政治化审判。",[
        sec("v144_xy1","早年要求让章奏回到召对和廷议","夏言任给事中时，主张皇帝每日阅章、召阁臣面决，大事交廷臣集议，避免近侍传旨绕过内阁。他清查亲军与京卫冗员，列传称汰三千二百人；这是官府核减口径，不能推定所有名额都是虚冒或人员立即获得安置。制度意义在于恢复信息进入决策的公开路径。后来他自己掌权时也会扩大逮讯，这种前后张力比单纯‘敢言名臣’更值得观察。",S196,["v144_estates_eunuchs"],["houcong"]),
        sec("v144_xy2","归还庄田把宫廷特权落实到土地问题","嘉靖初夏言参与勘查庄田，要求归还被夺民产，并反对外戚、王府通过投献继续扩地。庄田来源包含赐予、购买、投献与侵夺，不能一概判定；实际归还还要处理租佃、欠租和地界。行动说明所谓清明初政并不只是换人，而涉及家庭能否保有土地和向谁纳租。若只记他后来写青词、任首辅，便会失去早期政策为何获得声望的社会基础。",S196,["v144_estates_eunuchs"],["m144_zhangcong"]),
        sec("v144_xy3","由礼制工程与文字能力进入皇帝私人信任","夏言后来参与郊祀、庙制等礼仪工程，以文辞和青词获得世宗信任，升至首辅。他与早期议礼诸臣对立，使皇帝一度认为其不结党；但这种判断仍建立在个人好恶和直接接触上。礼制并非无成本的象征，坛庙营建、仪仗和典章都需财政与劳役。夏言借礼制进入中枢，也说明在世宗长期重视斋醮与名分的政治环境中，文字能力可以成为实际权力资源。",S196,["v13_jiajing_minglun"],["m144_zhangcong","m40_yansong"]),
        sec("v144_xy4","支持曾铣复套时，战略愿望压过了稳定论证","夏言希望建立边功，支持曾铣以六万兵、五十日粮进取河套。方案试图改变被动防守，却遭其他边臣质疑补给和守成。皇帝最初奖许，随后追问出师名义、粮饷与成功把握；夏言未能建立能承受态度变化的集体决策记录。支持方案不是犯罪，问题在于高度风险政策依靠密疏与个人知遇，一旦皇帝转向，参与者便从受奖者变成罪人。",["v144_ms196","v144_ms204"],["v144_hetao_plan"],["m144_zengxian","m144_wengwanda"]),
        sec("v144_xy5","遭严嵩构陷，不等于晚年用权没有问题","严嵩、崔元、陆炳等利用世宗疑虑和仇鸾奏疏攻击夏言，受贿指控缺少证据，最终处死明显带有政治化审判性质。同时列传也记夏言再起后逮讯巡抚、斥逐官员，权势扩张令朝臣畏惧。受害者可以曾是强势执政者，这两点并不冲突。隆庆时平反说明定罪失去合法性，却不能把全部执政记录改写成无瑕。区分政策责任、程序违法和私人构陷，才是可靠评价。",["v144_ms196","v144_ms204","v144_ms18"],["v144_hetao_trial"],["m40_yansong","m144_qiuluan"]),
      ]),
      article("m144_zengxian","曾铣：一份没有实施的河套方案，应当怎样评价","进取愿望、后勤预算、地方分歧与政治审判必须分开，后来边患不能替未实施计划证明必胜。",[
        sec("v144_zx1","辽东军乱与临清筑城塑造了强硬履历","曾铣早年处理辽东军士哗变，重惩首事者；在山东又推动临清外城建设。列传以果断知兵塑造他，也记其执法严酷。军乱成因涉及欠饷、指挥与军户生活，不能只用军纪败坏解释；城墙工程也需要民夫、材料与后续守备。他进入三边前已经形成通过整军和工程降低风险的治理路径，这既解释其自信，也可能使他低估更大范围行动的复杂性。",S204,["v144_hetao_plan"],[]),
        sec("v144_zx2","六万兵与五十日粮是方案参数，不是已经动员","面对河套成为蒙古诸部活动基地，曾铣提出春夏之交以锐卒六万、山东枪手二千，携五十日粮进军，并规划定边至黄甫川约一千五百里墙线。数字来自奏议，反映他试图计算季节、马草与火器优势；它们并不证明兵已齐、粮能到或敌方必按预期反应。将计划参数写成实际战果，是历史科普最常见的误读之一。",S204,["v144_hetao_plan"],["m144_altan"]),
        sec("v144_zx3","地方反对意见集中在粮运、协同与长期守成","延绥、陕西、宁夏等巡抚迟迟不能形成一致意见，翁万达亦认为进取风险过高。反对者并非必然怯战：远距离运粮、各镇兵权、冬春气候以及占领后驻守都需回答。曾铣也不是只求一战，他同时提出修墙和营阵。合理评价应把主动出击、防线建设、互市和维持现状作为多种方案比较，而不是把支持者写成爱国、质疑者写成畏敌。",["v144_ms204","v144_ms198"],["v144_hetao_plan"],["m144_wengwanda","m144_xiayan"]),
        sec("v144_zx4","皇帝先鼓励后追问，廷议随之整体转向","世宗先称赞恢复之议并拨初费二十万两，后来突然询问师出是否有名、兵食是否充足、成功是否可必。严嵩顺势反对，廷臣也改此前意见。追问本身是高风险决策应有内容，危险在于没有稳定评审程序：同一批人依皇帝态度迅速翻转，政策争论立刻变成人身归责。曾铣被逮，言官因先前不反对而廷杖，显示决策记录未能保护诚实意见。",S204,["v144_hetao_trial"],["houcong","m40_yansong"]),
        sec("v144_zx5","无证受贿指控被改造成死刑依据","仇鸾与曾铣有旧怨，严嵩一方代拟奏疏，指称克饷、行贿；《明史》明确说指控没有证据。法司最初按边帅失事拟罪，皇帝要求改用交结近侍律处斩，曾铣家属受牵连。不能以官修史一句话证明每个细节，但审罪条文随政治要求改变、相关人受酷刑逼供，足以说明程序严重失真。后来俺答入寇也不能证明复套必胜，只能说明处死没有解决边防结构问题。",S204,["v144_hetao_trial"],["m144_qiuluan","m144_xiayan"]),
      ]),
      article("m144_qiuluan","仇鸾：危机中的快速授权，为何没有换来可靠防务","从河套案脱罪到节制天下勤王兵，他的上升揭示皇帝在恐惧中选择个人统帅的制度代价。",[
        sec("v144_ql1","甘肃旧怨使他成为河套案中的直接受益者","仇鸾镇甘肃时军纪受议，并因阻挠等事被曾铣弹劾下狱。河套政策逆转后，他的奏疏成为攻击曾铣、夏言的材料，随后获释。翁万达在广西时也曾惩治仇鸾部下横暴，说明问题不只来自政敌事后书写。不过奏疏是否完全由严嵩代拟、每项罪名如何形成，仍须注明列传来源。可以确定的是，私人旧怨进入国家战略审判，受益者很快回到军权中心。",["v144_ms204","v144_ms198"],["v144_hetao_trial"],["m144_zengxian","m40_yansong","m144_wengwanda"]),
        sec("v144_ql2","庚戌之变中，等待战机与保存实力不能简单等同","俺答逼近北京时，仇鸾率大同兵入援，获授平虏大将军并节制诸路。他在东直门外观望，曾以死人首级报功，部队又掠夺居民。守城将领是否应在兵力不明时出战，本可讨论；冒功和扰民则是另一问题。若把所有不战都说成怯懦，会忽视野战风险；若以谨慎解释全部行为，又会抹去军纪和报告造假。军事评价必须把战术选择与制度责任分开。",["v144_ms204","v144_ms18"],["v144_gengxu_supply","v144_gengxu_people"],["m144_altan"]),
        sec("v144_ql3","个人受宠掩盖不了军籍、武库和粮饷失灵","危机时京军名册虚额，现役中又多老弱或被权贵役使；武库发甲仗还索取常例，援军缺粮。丁汝夔与杨守谦被处死后，仇鸾成为胜利者，却没有修复这些链条。皇帝把希望集中在一名边将和其亲兵，短期可形成指挥中心，长期则让各路军队更依附恩宠。仇鸾的故事不应只是奸将传，而应说明替罪与破格授权为何会遮住组织性缺陷。",S204,["v144_gengxu_supply"],["houcong"]),
        sec("v144_ql4","压制商大节民兵显示统一指挥也可能排斥有效力量","商大节在京师募民兵四千，分等给饷。仇鸾担心这支兵不受自己节制，要求其承担四郊防务，又频繁调走所属力量；商大节申辩后被下狱判死，最终死于狱中。独立武装确需明确指挥，但将不相容意见转成刑狱，会让防务失去纠错。民兵数量和训练效果来自列传，不能夸大为扭转战局；其遭遇仍显示危机后的整军被私人权力竞争污染。",S204,["v144_gengxu_people"],[]),
        sec("v144_ql5","死后追戮说明恩宠政治不能提供稳定责任","1552年仇鸾病死，随后被揭发并遭剖棺戮尸，首级传示边镇，相关人员受惩。死后惩罚具有强烈政治示范，不等于此前所有命令自动无效，也不应让酷烈处置替代逐项审理。他生前因皇帝信任压过异议，死后又在信任逆转时承受极刑，前后都缺少稳定程序。真正的教训不是换一位更忠诚的统帅，而是军功核验、军纪、粮饷与申诉不能随个人宠辱升降。",["v144_ms18","v144_ms204"],["v144_horse_markets"],["houcong","m40_xujie"]),
      ]),
      article("m144_wengwanda","翁万达：边墙之外，宣大防务还需要什么","工程、情报、军纪、将领和边贸共同构成防线；只看长城长度，会遗漏最难维持的部分。",[
        sec("v144_wwd1","从广西治理到安南交涉，先学习有限目标","翁万达任梧州知府时惩治仇鸾骄兵，后参与安南事务。他主张能以威慑使莫登庸归附优于彻底征灭，并利用释放间谍、传递兵威促成投降。官修史突出其谋略，不能忽略明军集结和地方武力压力，也不能把结果称为纯和平谈判。重要的是他将目标分为归附、威慑和歼灭，知道战争成本会随目标升级，这种有限目标思维后来也进入北边政策。",S198,[],["m144_qiuluan"]),
        sec("v144_wwd2","墙、堡、墩台只有和守军道路结合才是防线","总督宣大后，翁万达主持大同东路、宣府西路修墙设堡，阶段奏报包含墙一百九十二里、堡七座、墩台一百五十四座等。数字说明工程规模，却不能相加成今日可精确定位的完整长城。他还处理斩崖、道路、驻军和将领更换。墙体可延缓骑兵、引导敌路，不能自行侦察或作战；若缺粮饷、维修与机动兵，它也会成为昂贵静态设施。",S198,["v144_wall_network"],["m144_altan"]),
        sec("v144_wwd3","严军纪与善用降人构成情报体系的两面","翁万达检查守卒离岗，严禁擅杀投降者，又优待降人以获取敌情。严格惩处可提高防秋到岗率，也可能在上报压力下造成恐惧；依靠降人情报能理解部众动向，却需防范误报和私人报复。列传用具体故事突出其御将能力，不宜把每次战果都归给一人。可取之处在于把侦候、军纪、奖惩和前线部署视为同一系统，而不是等敌军越墙后才临时征援。",S198,["v144_wall_network"],[]),
        sec("v144_wwd4","反对复套不是消极，而是另一套成本判断","曾铣主张大规模恢复河套时，翁万达从兵力、粮运与长期驻守提出疑虑。两人面对同一威胁，却分别偏向主动改变战略纵深与巩固现有防线。后来的庚戌之变不能自动证明曾铣正确，也不能证明翁万达方案足够；它只说明现有体系仍有巨大缺口。高质量边政史应展示可选方案和机会成本，使读者看到大臣争论的不只是勇怯，而是谁承担征发、失败与守成。",["v144_ms198","v144_ms204"],["v144_hetao_plan"],["m144_zengxian"]),
        sec("v144_wwd5","多次建议贡市，是试图给战争加入可控替代项","俺答部请求贡市时，翁万达认为可以在边臣可控范围内处理；世宗担心示弱和安全风险，屡次拒绝，往来使者被杀又强化报复。互市不能保证和平，也可能被用于侦察或资助强部；完全堵塞交易同样会放大走私、抢掠与牧业灾年的压力。翁万达最终因守制迟行、严嵩不满和仇鸾旧怨失去信任，说明经验丰富的边臣也无法在个人化决策中维持政策连续。",["v144_ms198","v144_ms327"],["v144_trade_envoys"],["m144_altan","houcong"]),
      ]),
      article("m144_altan","俺答汗：从蒙古内部与明蒙边贸重新理解嘉靖北边","他既是发动掠夺战争的首领，也是土默特扩张、牧业交换与长期封贡谈判中的行动者。",[
        sec("v144_aa1","先把俺答放回蒙古诸部竞争，而非只写边患","俺答是达延汗之孙、土默特部首领，在蒙古右翼诸部扩张中经营河套与丰州川。他与察哈尔等势力既合作又竞争，军事行动服务于部众、牧地、财富和政治声望。明朝本纪和列传常用寇称呼其军队，这是遭袭国家的边政语言；科普可以保留战争责任，同时提示材料视角。若只把他写成从北方周期出现的敌人，便无法解释为何贸易、内部分裂和后来的封贡会改变行为。",S327,[],[]),
        sec("v144_aa2","板升聚落与跨境人口改变了草原经济","俺答控制区出现被称为板升的农业聚落，汉人逃亡者、工匠和商人参与耕作、建筑与交换。它们帮助蒙古贵族获得粮食和手工业品，也使明朝担心逃人、武器和情报外流。不能把所有越境者都称为自愿投敌：逃役、灾荒、俘掠和谋生路径各不相同。边境不是一道完全密封的线，而是国家禁令、部众控制与日常贸易不断拉扯的社会空间。",S327,["v144_trade_envoys"],[]),
        sec("v144_aa3","求贡互市与武装施压往往同时发生","俺答多次要求向明朝进贡、开市，希望以马畜换取布帛、粮食和金属。请求并不排除军事威胁，掠夺也不意味着没有交易需求。明朝担心封号承认、边将舞弊和强部坐大，曾拒绝或杀来使；双方由此形成封锁、走私、报复和再谈判循环。贸易不是战争的道德借口，但它是解释冲突节奏的必要变量。把互市写成买和平或把拒市写成坚守原则，都过于简单。",["v144_ms327","v144_ms198"],["v144_trade_envoys","v144_horse_markets"],["m144_wengwanda","houcong"]),
        sec("v144_aa4","庚戌之变暴露的是明朝整条防务链","1550年俺答军越古北口，经密云、通州抵近北京，掠夺畿内后退去。其军队对沿途居民造成杀掠，责任不能因讨论明朝失误而淡化；同时，京军虚额、军器迟发、情报错误、援军缺粮与指挥争议解释了为何首都如此被动。俺答未攻下北京不等于行动无影响，难民、村落损失和恐慌推动外城、营制与马市变化。战役史应把攻击者行动与防御者制度同时呈现。",["v144_ms18","v144_ms204","v144_ms327"],["v144_gengxu_supply","v144_gengxu_people"],["m144_qiuluan"]),
        sec("v144_aa5","从短暂马市到隆庆封贡，说明政策仍可转向","庚戌后宣大短暂开设马市，次年关闭，边境继续冲突。俺答晚年因孙把汉那吉投明等事件与明朝重新谈判，隆庆年间获得封号并形成较稳定互市，这属于下一阶段，不能倒写成嘉靖时双方早已注定和解。它却证明战争并非唯一制度选择。互市后的和平也不绝对，仍有部众差异、走私与边将问题；其意义在于让可预测交换逐渐替代大规模劫掠的收益结构。",S327,["v144_horse_markets"],["m144_wengwanda"]),
      ]),
    ]
    extensions={
      "m144_zhangcong":"再向基层追一步，礼制胜负还会改变官员升迁、地方祭祀与公文称谓。普通百姓未必直接参与经义辩论，却要通过赋役、仪式和司法感受中枢重组。现存材料主要由胜负双方官员留下，很少保存书吏、差役和受牵连家庭的声音；因此可以确认制度动作，却不替沉默者编造一致态度。把这些空白明确写出，能够避免将一场覆盖全国行政的变化缩成几位阁臣的口舌之争。",
      "m144_guie":"还应注意，奏议中的‘民’并非利益完全一致的整体。免税有利于实际纳粮者，开中牵动盐商、灶户和边军，开放闲地又可能与军防或原有使用者冲突。政策同时出现于一位强硬排异的执政者身上，恰好说明内容正确与程序可靠是两套问题。阅读桂萼时，既不因其政治手段否定所有方案，也不因方案看似惠民而替其用权方式背书。",
      "m144_xiayan":"夏言留下的另一层警示，是制度倡议者掌权后也可能偏离早年倡导的集议。皇帝直接召用、青词知遇与首辅拟旨，使公开程序和私人信任并存；失去信任时，曾经绕开的程序也无法保护自己。现存列传多由后来政治结果倒叙人物性格，故本篇只把可核职务、奏疏与案件相连，不把严嵩获胜解释为夏言必然失败，更不把平反等同于所有政策正确。",
      "m144_zengxian":"对未实施方案的评价还要承认反事实无法验证：若出兵，可能获得阶段战果，也可能因补给中断扩大伤亡；若不出兵，防线仍需承担持续袭扰。史料只能展示当时掌握的信息、预算与异议，不能替历史选择补写唯一正确答案。曾铣之死的确定问题是审判受政治压力扭曲，而不是他提出的每项军事估算因此都正确。区分程序正义与战略成败，才能避免用冤案制造新的英雄神话。",
      "m144_qiuluan":"普通士兵也不应只作为仇鸾私人军队的背景。他们可能来自边镇军户，长途入援后面对欠饷、饥饿和陌生城市；军纪犯罪必须追究，供给与指挥责任也要上溯。史书较少留下这些士兵及受害居民的个别证词，所以本文不推定每名军士都参与掠夺。把统帅责任、组织条件和个人行为分层，既不会稀释暴力，也能解释为何更换统帅后相似问题仍可能重现。",
      "m144_wengwanda":"工程史还需追问谁运石、烧砖、守台和供粮。列传记录五十余日竣工，是官员报功的时间尺度；墙体此后的维修、士兵轮换和地方徭役不在同一数字中。边墙保存至今的可见性，也容易让人高估建筑、低估情报与谈判。翁万达的价值不在于证明某种万能边策，而在于把多种工具组合，并承认每项工具都有财政成本、误判风险和需要持续维护的行政条件。",
      "m144_altan":"俺答活动跨越嘉靖与隆庆，不能用1550年一次兵临城下定义七十余年生命，也不能由后来的封贡淡化此前杀掠。蒙古一侧材料较少进入明代官修史，使部众内部意见、妇女生产和普通牧户受战争影响更难重建。可靠叙述应保留这种不对称：对明朝记录明确的路线、诏令和市场谨慎陈述，对蒙古内部动机只作有来源的结构解释，并把未知留在文字表面，而非用想象填平。",
    }
    for a in readings:
        a["sections"][-1]["text"] += extensions[a["person"]]
        upsert(d["articles"],a,key="person")
    emp=next(x for x in d["articles"] if x["person"]=="houcong")
    sm={x["id"]:x for x in emp["sections"]}
    # Preserve prose/audio; enrich only related paths.
    for sid, ps, es in [
      ("houcong-1",["m143_yangtinghe","m144_zhangcong","m144_guie"],["v2l_greatrites","v144_left_gate"]),
      ("houcong-2",["m144_zhangcong","m144_guie","m144_xiayan"],["v144_lifuda","v144_estates_eunuchs"]),
      ("houcong-4",["m144_xiayan","m144_zengxian","m40_yansong"],["v144_hetao_plan","v144_hetao_trial"]),
      ("houcong-5",["m144_wengwanda","m144_qiuluan","m144_altan"],["v144_wall_network","v144_gengxu_supply","v144_horse_markets"]),
      ("houcong-7",["m144_altan"],["v144_beijing_outer_city","v144_1556_earthquake"]),
    ]:
        if sid in sm:
            sm[sid]["people"] = list(dict.fromkeys(sm[sid].get("people",[])+ps))
            sm[sid]["events"] = list(dict.fromkeys(sm[sid].get("events",[])+es))
    for x in [s["id"] for s in src]:
        if x not in emp["sources"]: emp["sources"].append(x)
    pairs=[
      ("m144_zhangcong","m144_guie","共同推动大礼议并进入中枢","与其同为议礼核心，亦在用人和案件中互相呼应","1521—1530","共同立场不等于所有政策与责任完全一致",["v144_ms196"]),
      ("m144_zhangcong","m143_yangtinghe","以继统不继嗣反对其礼制方案","坚持孝宗皇统与宗法继嗣方案","1521—1524","学理争论后来因皇帝惩罚转为权力胜负",["v144_ms196","v144_ms17"]),
      ("m144_xiayan","m144_zengxian","在内阁支持其恢复河套计划","获其密疏支持并扩大出兵准备","1546—1548","支持战略不构成受贿证据，方案亦未实施",["v144_ms196","v144_ms204"]),
      ("m144_xiayan","m40_yansong","再起后压制其权势，终被其借河套案排挤","顺应皇帝疑虑反对复套并攻击其责任","1545—1548","政治构陷明确，但夏言执政亦非没有扩权",["v144_ms196"]),
      ("m144_zengxian","m144_qiuluan","任三边总督时弹劾其阻挠与军政问题","借旧怨奏劾并在其死后出狱","1546—1548","奏疏罪名含无证指控，应与可核实军纪问题分开",["v144_ms204"]),
      ("m144_wengwanda","m144_zengxian","质疑大规模复套的后勤与守成风险","主张主动进取，与其现地防御路线不同","1546—1548","是战略成本争论，不宜简化成勇怯",["v144_ms198","v144_ms204"]),
      ("m144_wengwanda","m144_altan","建议以受控贡市降低边境冲突","以贡市请求和军事压力同时回应明朝","1540年代","互市主张不等于无条件接受，战争责任也不能由贸易需求消除",["v144_ms198","v144_ms327"]),
      ("m144_qiuluan","m144_altan","庚戌时受命节制援军但未形成有效野战","率军深入畿辅并以压力促使明朝重议马市","1550—1552","双方材料战果口径不同，不作无来源精确统计",["v144_ms18","v144_ms204"]),
    ]
    for f,t,r,inv,p,n,s in pairs: association(d,{"from":f,"to":t,"role":r,"inverse":inv,"period":p,"note":n,"sources":s})
    d["version"]=118; d["reviewed"]="2026-10-31"
    DATA.write_text(json.dumps(d,ensure_ascii=False,indent=2)+"\n")
    n=json.loads(NARRATION.read_text())
    changed={x["person"] for x in readings}
    n["entries"]=[x for x in n["entries"] if x["articleID"] not in changed]
    NARRATION.write_text(json.dumps(n,ensure_ascii=False,indent=2)+"\n")

